1	'use server'
2	
3	import { redirect } from 'next/navigation'
4	import { revalidatePath } from 'next/cache'
5	import { getAuthenticatedUser } from '@/lib/supabase/server'
6	import {
7	  createFlashEvent,
8	  updateFlashEvent,
9	  publishFlashEvent,
10	  cancelFlashEvent,
11	  addDesign,
12	  updateDesign,
13	  removeDesign,
14	  reorderDesigns,
15	  blockSlot,
16	  unblockSlot,
17	} from '@/lib/flash-events/mutations'
18	import {
19	  flashEventCreateSchema,
20	  flashEventUpdateSchema,
21	  flashDesignCreateSchema,
22	  flashDesignUpdateSchema,
23	} from '@/lib/flash-events/schemas'
24	import { logger } from '@/lib/logger'
25	
26	type ActionResult = { success: boolean; error?: string }
27	
28	// ── Create ────────────────────────────────────────────────────────────────────
29	
30	export async function createFlashEventAction(
31	  formData: FormData
32	): Promise<ActionResult & { id?: string }> {
33	  const auth = await getAuthenticatedUser()
34	  if (!auth) return { success: false, error: 'Not authenticated' }
35	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
36	    return { success: false, error: 'Insufficient permissions' }
37	  }
38	
39	  const raw = {
40	    title: formData.get('title'),
41	    slug: formData.get('slug') || undefined,
42	    description: formData.get('description') || undefined,
43	    eventDate: formData.get('eventDate'),
44	    startTime: formData.get('startTime'),
45	    endTime: formData.get('endTime'),
46	    slotDurationMin: Number(formData.get('slotDurationMin')),
47	    slotPriceCents: Number(formData.get('slotPriceCents') ?? 0),
48	    depositCents: Number(formData.get('depositCents') ?? 0),
49	    currency: formData.get('currency') || 'USD',
50	    maxSlots: formData.get('maxSlots') ? Number(formData.get('maxSlots')) : undefined,
51	    coverImageUrl: formData.get('coverImageUrl') || undefined,
52	    flyerUrl: formData.get('flyerUrl') || undefined,
53	    locationId: formData.get('locationId') || undefined,
54	    artistId: formData.get('artistId') || undefined,
55	    public: formData.get('public') !== 'false',
56	  }
57	
58	  const parsed = flashEventCreateSchema.safeParse(raw)
59	  if (!parsed.success) {
60	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
61	  }
62	
63	  try {
64	    const event = await createFlashEvent(auth.studioId, parsed.data)
65	    revalidatePath('/flash-events')
66	    return { success: true, id: event.id }
67	  } catch (err) {
68	    logger.error({ err }, 'createFlashEventAction failed')
69	    const message = err instanceof Error ? err.message : 'Failed to create event'
70	    return { success: false, error: message }
71	  }
72	}
73	
74	// ── Update ────────────────────────────────────────────────────────────────────
75	
76	export async function updateFlashEventAction(
77	  eventId: string,
78	  formData: FormData
79	): Promise<ActionResult> {
80	  const auth = await getAuthenticatedUser()
81	  if (!auth) return { success: false, error: 'Not authenticated' }
82	  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
83	    return { success: false, error: 'Insufficient permissions' }
84	  }
85	
86	  const raw: Record<string, unknown> = {}
87	  const title = formData.get('title')
88	  if (title) raw.title = title
89	  const slug = formData.get('slug')
90	  if (slug) raw.slug = slug
91	  const description = formData.get('description')
92	  if (description !== null) raw.description = description || null
93	  const eventDate = formData.get('eventDate')
94	  if (eventDate) raw.eventDate = eventDate
95	  const startTime = formData.get('startTime')
96	  if (startTime) raw.startTime = startTime
97	  const endTime = formData.get('endTime')
98	  if (endTime) raw.endTime = endTime
99	  const slotDurationMin = formData.get('slotDurationMin')
100	  if (slotDurationMin) raw.slotDurationMin = Number(slotDurationMin)
101	  const slotPriceCents = formData.get('slotPriceCents')
102	  if (slotPriceCents !== null) raw.slotPriceCents = Number(slotPriceCents)
103	  const depositCents = formData.get('depositCents')
104	  if (depositCents !== null) raw.depositCents = Number(depositCents)
105	  const maxSlots = formData.get('maxSlots')
106	  if (maxSlots !== null) raw.maxSlots = maxSlots ? Number(maxSlots) : null
107	  const coverImageUrl = formData.get('coverImageUrl')
108	  if (coverImageUrl !== null) raw.coverImageUrl = coverImageUrl || null
109	  const flyerUrl = formData.get('flyerUrl')
110	  if (flyerUrl !== null) raw.flyerUrl = flyerUrl || null
111	  const locationId = formData.get('locationId')
112	  if (locationId !== null) raw.locationId = locationId || null
113	  const artistId = formData.get('artistId')
114	  if (artistId !== null) raw.artistId = artistId || null
115	  const isPublic = formData.get('public')
116	  if (isPublic !== null) raw.public = isPublic !== 'false'
117	
118	  const parsed = flashEventUpdateSchema.safeParse(raw)
119	  if (!parsed.success) {
120	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
121	  }
122	
123	  try {
124	    await updateFlashEvent(auth.studioId, eventId, parsed.data)
125	    revalidatePath(`/flash-events/${eventId}`)
126	    revalidatePath('/flash-events')
127	    return { success: true }
128	  } catch (err) {
129	    logger.error({ err, eventId }, 'updateFlashEventAction failed')
130	    const message = err instanceof Error ? err.message : 'Failed to update event'
131	    return { success: false, error: message }
132	  }
133	}
