135	// ── Publish ───────────────────────────────────────────────────────────────────
136	
137	export async function publishFlashEventAction(eventId: string): Promise<ActionResult> {
138	  const auth = await getAuthenticatedUser()
139	  if (!auth) return { success: false, error: 'Not authenticated' }
140	  if (!['owner', 'admin'].includes(auth.role)) {
141	    return { success: false, error: 'Only owners and admins can publish events' }
142	  }
143	
144	  try {
145	    const { slotsGenerated } = await publishFlashEvent(auth.studioId, eventId)
146	    revalidatePath(`/flash-events/${eventId}`)
147	    revalidatePath('/flash-events')
148	    logger.info({ eventId, slotsGenerated }, 'Flash event published')
149	    return { success: true }
150	  } catch (err) {
151	    logger.error({ err, eventId }, 'publishFlashEventAction failed')
152	    const message = err instanceof Error ? err.message : 'Failed to publish event'
153	    return { success: false, error: message }
154	  }
155	}
