178	// ── Designs ───────────────────────────────────────────────────────────────────
179	
180	export async function addDesignAction(
181	  eventId: string,
182	  formData: FormData,
183	  styleTagIds?: string[]
184	): Promise<ActionResult> {
185	  const auth = await getAuthenticatedUser()
186	  if (!auth) return { success: false, error: 'Not authenticated' }
187	
188	  const raw = {
189	    title: formData.get('title'),
190	    imageUrl: formData.get('imageUrl'),
191	    sizeDescription: formData.get('sizeDescription') || undefined,
192	    placementOptions: formData.get('placementOptions') || undefined,
193	    priceCents: formData.get('priceCents') ? Number(formData.get('priceCents')) : undefined,
194	    displayOrder: formData.get('displayOrder') ? Number(formData.get('displayOrder')) : 0,
195	    styleTagIds: styleTagIds?.length ? styleTagIds : undefined,
196	  }
197	
198	  const parsed = flashDesignCreateSchema.safeParse(raw)
199	  if (!parsed.success) {
200	    return { success: false, error: parsed.error.errors[0]?.message ?? 'Validation failed' }
201	  }
202	
203	  try {
204	    await addDesign(auth.studioId, eventId, parsed.data)
205	    revalidatePath(`/flash-events/${eventId}`)
206	    return { success: true }
207	  } catch (err) {
208	    logger.error({ err, eventId }, 'addDesignAction failed')
209	    return { success: false, error: 'Failed to add design' }
210	  }
211	}
