306	// ── Delete (redirect after) ───────────────────────────────────────────────────
307	
308	export async function deleteFlashEventAction(eventId: string): Promise<void> {
309	  const auth = await getAuthenticatedUser()
310	  if (!auth) redirect('/login')
311	  if (!['owner', 'admin'].includes(auth.role)) redirect(`/flash-events/${eventId}`)
312	
313	  // Cancel first (frees slots), then delete
314	  try {
315	    await cancelFlashEvent(auth.studioId, eventId)
316	  } catch {
317	    // Best-effort
318	  }
319	
320	  const { createClient } = await import('@/lib/supabase/server')
321	  const supabase = await createClient()
322	  await supabase
323	    .from('flash_events')
324	    .delete()
325	    .eq('id', eventId)
326	    .eq('studio_id', auth.studioId)
327	
328	  revalidatePath('/flash-events')
329	  redirect('/flash-events')
330	}
